ALTER TABLE "work_reports" DROP CONSTRAINT "work_report_photo_metadata";--> statement-breakpoint
ALTER TABLE "work_reports" ADD CONSTRAINT "work_report_photo_metadata" CHECK (("work_reports"."storage_key" IS NULL AND "work_reports"."filename" IS NULL AND "work_reports"."mime_type" IS NULL AND "work_reports"."size" IS NULL) OR ("work_reports"."storage_key" IS NOT NULL AND "work_reports"."filename" IS NOT NULL AND "work_reports"."mime_type" IS NOT NULL AND "work_reports"."size" IS NOT NULL AND "work_reports"."mime_type" IN ('image/jpeg','image/png','image/webp') AND "work_reports"."size" > 0 AND "work_reports"."size" <= 10485760));